import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_transpose_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void matmul_transpose_kernel(const float* A, const float* B, float* C,
                                        int M, int K, int N) {
    // Each block covers a region of size blockDim.x x blockDim.y in the output
    // row = m, col = n
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < M && col < N) {
        float val = 0.0f;
        for (int i = 0; i < K; i++) {
            // A is (K, M) in memory; but we treat it as (M, K) with a transpose
            // so A_{k, m} = A[k*M + m]. We want A_{m, i} = A[i*M + row] if row = m
            // B is (K, N): B_{k, n} = B[k*N + n]
            val += A[i * M + row] * B[i * N + col];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must share the K dimension");

    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(1);

    auto options = A.options();
    auto C = torch::zeros({M, N}, options);

    const int block_x = 16;
    const int block_y = 16;
    dim3 block(block_x, block_y);
    dim3 grid((M + block_x - 1) / block_x, (N + block_y - 1) / block_y);

    matmul_transpose_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N
    );

    return C;
}
"""

matmul_transpose_cpp_source = r"""
torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_transpose = load_inline(
    name="matmul_transpose",
    cpp_sources=matmul_transpose_cpp_source,
    cuda_sources=matmul_transpose_source,
    functions=["matmul_transpose_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_transpose = matmul_transpose

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_transpose.matmul_transpose_cuda(A, B)
